package com.auditlog.service.exception;import java.time.Instant;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler({IllegalArgumentException.class,NoSuchElementException.class})ResponseEntity<Map<String,Object>> known(RuntimeException e){HttpStatus s=e instanceof NoSuchElementException?HttpStatus.NOT_FOUND:HttpStatus.BAD_REQUEST;return ResponseEntity.status(s).body(Map.of("timestamp",Instant.now(),"status",s.value(),"error",s.getReasonPhrase(),"message",e.getMessage()));}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<Map<String,Object>> validation(MethodArgumentNotValidException e){return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"status",400,"error","VALIDATION_ERROR","message","Request validation failed","details",e.getBindingResult().getFieldErrors().stream().map(x->Map.of("field",x.getField(),"message",Objects.toString(x.getDefaultMessage(),"invalid"))).toList()));}}
